/* course20.js — content of Course 20 (Networking to the cloud and VPN to the cloud; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 20 — Networking to the cloud and VPN to the cloud (the cloud as someone else’s datacenter behind the network,
   shared responsibility, site-to-site and remote-access VPN, publishing a service via
   DNAT and a load balancer, a cloud DMZ and security groups, resilience and design).
   Scene c20Net: PC / USER — SW — FW — NET — CG (cloud gateway) — WEB / WEB2 / DB (VPC).
   ============================================================ */
var C20R={pc:[58,85],usr:[58,240],sw:[172,162],fw:[295,162],net:[410,162],cg:[520,162],web:[610,80],web2:[610,175],db:[610,268]};
