/* ---------- L6M2 — Where to put data ---------- */
function renderC20Data(){return c20P('clq',
  'Connection resilience is one half; the other is the <b>fate of the data</b>. The cloud tempts a dangerous comfort: ‘the data is in the cloud, so surely it is safe’. It is not – or more precisely, it is safe only from what the provider committed to protect it from, and that is not everything. Two things must be thought through. The first is <b>backups</b>. The provider looks after their hardware, but <b>will not delete your data by accident for you and will not protect it from your mistake</b>: when someone deletes the database, runs the wrong script or ransomware encrypts you, the cloud dutifully stores that change. So a backup must exist and be <b>separate</b> – another account, another place, ideally such that it cannot be deleted by the same access that deleted the data. The classic rule is to keep several copies in several places and at least one out of reach of everyday operations. And a backup you never tried to <b>restore</b> is not a backup – it is a hope. The second thing is <b>regions</b>. The provider has datacenters in various parts of the world and your data physically sits in the one you chose (or was chosen for you). This has two impacts. Security: a whole region can have an outage, so truly critical services are spread across <b>two regions</b> so one disaster does not sink them. And legal: where the data sits, the local laws apply – for personal data the region is a decision, not a detail. Conceptually take away this: <b>the cloud moves where the data sits, but it does not take from you the responsibility that it survives</b>.',
  [['a separate backup','a copy in another place and account, not deletable by the same access as the original data.'],['regions','where the data physically sits; it decides resilience against outage and which laws apply.']]);}
function mountC20Data(){c20Mount('clq',[
  {glow:c20g('db','--amber'),dyn:c20lbl('‘data is in the cloud, so it is safe’ – it is not','--amber'),cap:'The cloud tempts the comfort ‘data is in the cloud, so it is safe’. But it does not protect you from your own mistake.'},
  {glow:c20g('db','--red')+c20g('web2','--red'),dyn:c20pkt('M 610 268 L 610 175','--red')+c20lbl('a bad delete the cloud dutifully stores','--red'),cap:'When someone deletes the database or ransomware encrypts you, the cloud <b>dutifully stores</b> that change. A backup must exist.'},
  {glow:c20g('db','--green')+c20g('cg','--green'),dyn:c20pkt('M 610 268 L 520 162','--green','1.9s')+c20lbl('a separate backup; untested restore is a hope','--green'),cap:'A backup must be <b>separate</b> – another place and account, out of reach of everyday operations. And an untested restore is a hope, not a backup.'},
  {glow:c20g('web','--cyan')+c20g('db','--cyan'),dyn:c20lbl('regions: two for critical; local law applies','--cyan'),cap:'<b>Regions</b>: a whole region can fail, so spread critical services across two. And where data sits, local laws apply.'}
]);}
/* ---------- L6M3 — A cloud network checklist ---------- */
function renderC20Checklist(){return c20P('clr',
  'To close, a <b>checklist</b> to take to every cloud network design – it sums up the whole course into questions you must be able to answer. <b>Connection:</b> How does the company reach the private servers – through a tunnel, not over the internet? Is the tunnel <b>doubled</b> and do you know what happens when it drops? Do you have more than one internet link and have you tested failover? <b>People’s entry:</b> Do remote users come over a remote-access VPN with strong verification? Is access removed on departure? Do they have <b>privileges just as narrow as in the office</b> after login? <b>Publishing:</b> Does <b>only what should be public</b> have a public address? For every open port, answer: must a stranger on the internet see this? Is there a load balancer before the web farm? <b>Segmentation:</b> Are public and private subnets separated? Is the database in the private one, with no path from outside? Do servers have a default deny and are the rules narrow and described? Is anything permitting ‘from anywhere’ to management? <b>Data:</b> Is there a separate backup and have you tried to restore it? Did you consciously decide on the region? And the last, connecting question you know from security: <b>if I captured the web server, where would I get from here?</b> When the answer is ‘to one database port and nothing more’, your cloud is well designed. A final tip: <b>pick the one answer that hurt most today and fix it.</b> The cloud is not secured at once – it is secured by making that list one missing boundary shorter next time. Congratulations on finishing; now try it in the simulator on the multi-WAN failover task.',
  [['the checklist','connection, people’s entry, publishing, segmentation, data – five areas of questions for a cloud network.'],['where do I get from here','the connecting question: from a captured web to one database port and no more = a good design.']])
  +courseCTA('clrTask','Test connection resilience: drop the primary link and watch the switch to the backup: the task ‘Multi-WAN failover’.','Open the task');}
function mountC20Checklist(){c20Mount('clr',[
  {glow:c20g('fw','--blue')+c20g('net','--blue')+c20g('cg','--blue')+c20g('db','--blue'),dyn:c20pkt('M 295 162 L 410 162 L 520 162 L 610 268','--blue','2.1s')+c20lbl('connection: a doubled tunnel with failover','--blue'),cap:'<b>Connection</b>: to private servers via a tunnel, not the internet. Is it doubled? Do you have several links and tested failover?'},
  {glow:c20g('usr','--violet')+c20g('net','--violet')+c20g('cg','--violet')+c20g('web','--violet'),dyn:c20pkt('M 58 240 L 410 162 L 520 162 L 610 80','--violet','2.1s')+c20lbl('people: remote-access, verified, narrow','--violet'),cap:'<b>People’s entry</b>: remote-access with strong verification, access removed on departure, narrow privileges after login.'},
  {glow:c20g('net','--green')+c20g('cg','--green')+c20g('web','--green')+c20g('web2','--green'),dyn:c20pkt('M 410 162 L 520 162 L 610 80','--green')+c20lbl('publish and segment: only the web is public','--green'),cap:'<b>Publishing and segmentation</b>: only the web is public, a load balancer before the farm, the database in a private subnet with no path from outside.'},
  {glow:c20g('web','--red')+c20g('web2','--red')+c20g('db','--red'),dyn:c20pkt('M 610 80 L 610 175 L 610 268','--red','2.0s')+c20lbl('if I took the web, where would I reach? Fix one','--red'),cap:'The connecting question: <b>if I took the web, where would I reach?</b> One database port and no more = a good design. Pick one thing and fix it.'}
]);
  var b=$('clrTask');if(b)b.onclick=function(){courseTry('wan-failover');};
}

